import * as E from './duel-engine.mjs';
import {assets,hero} from './arena-art.mjs';
const $=id=>document.getElementById(id),screen=$('screen'),canvas=$('world'),ctx=canvas.getContext('2d');
let meta={},run=null,view='choose',category='weapons',preview=null,art,town,locked=false,animation=null,training=null,saveError=false;
try{meta={thorn:JSON.parse(localStorage.getItem(E.META)||'{}')?.thorn===true};run=E.load(localStorage.getItem(E.SAVE),meta);}catch{}
const button=(label,action,disabled=false,cls='')=>`<button data-do="${action}" ${disabled?'disabled':''} class="${cls}">${label}</button>`;
const heading=(title,sub='')=>`<div class="heading"><h1>${title}</h1><p>${sub}</p></div>`;
function save(){try{if(run)localStorage.setItem(E.SAVE,JSON.stringify(run));else localStorage.removeItem(E.SAVE);localStorage.setItem(E.META,JSON.stringify(meta));saveError=false;}catch{saveError=true;}$('save-note').textContent=saveError?'Saving unavailable. Keep this tab open to retain this journey.':'Saved on this browser.';}
function go(v){view=v;preview=null;render();}
function confirm(title,text,yes,fn){$('confirm-title').textContent=title;$('confirm-text').textContent=text;$('confirm-yes').textContent=yes;$('confirm-yes').onclick=()=>{$('confirm').close();fn();};$('confirm').showModal();}
$('confirm-no').onclick=()=>$('confirm').close();
function menu(){if(locked)return;$('forfeit').hidden=!run?.battle;$('menu').showModal();}
$('menu-button').onclick=menu;$('home').onclick=e=>{e.preventDefault();if(run?.battle||training)menu();else if(run&&!run.dead)go('town');};$('resume').onclick=()=>$('menu').close();
$('restart').onclick=()=>{$('menu').close();confirm('Start a new journey?','Your current coins, levels and equipment reset. Unlocked masters stay available.','Start fresh',()=>{run=null;training=null;animation=null;locked=false;save();go('choose');});};
$('forfeit').onclick=()=>{$('menu').close();confirm('Forfeit this fight?',run.tournament?'Tournament defeat ends this journey.':'You lose the listed gold, but can keep playing.','Forfeit',()=>{E.surrender(run,meta);save();go('result');});};
function compare(o){const a=E.stats(run),b=E.stats(o);return '<div class="comparison"><b>You</b><span></span><b>Rival</b>'+[['hp','Health'],['melee','Melee'],['ranged','Ranged'],['armor','Armor'],['magic','Magic'],['stride','Movement']].map(([k,n])=>`<span>${k==='magic'&&!run.spells.length?'—':a[k]}</span><span class="label">${n}</span><span>${k==='magic'&&!o.spells.length?'—':b[k]}</span>`).join('')+'</div>';}
function render(){const r=run,b=training?.battle||r?.battle;$('wallet').textContent=r?`Level ${r.level} · ${r.gold} gold`:'';
if(view==='choose'){screen.innerHTML=heading('Who will claim the crown?','Different fighters. Your own way to win.')+'<div class="choose-list">'+Object.entries(E.CLASSES).map(([k,c])=>button(`<strong>${c.title}</strong><small>${k==='thorn'&&!meta.thorn?'Defeat the Forest Master to unlock':c.trait}</small><small>${k==='dwarf'?'Starts with an axe':k==='ranger'?'Starts with a bow and blade':k==='mage'?'Starts with a staff and Lightning':'Starts with an axe'}</small>`,'choose:'+k,k==='thorn'&&!meta.thorn)).join('')+'</div>';}
if(view==='town')screen.innerHTML=`<div class="town-heading"><span class="tag">${r.crown?'THE FIRST CROWN IS YOURS':'THE ROAD TO THE FIRST CROWN'}</span><h1>Crownfall</h1></div><nav class="town-nav" aria-label="Town shops">${button('Weaponsmith','shop:weapons')}${button('Enter Arena','arena')}${button('Arcane Shop','shop:magic')}${button('Armory','shop:armor')}</nav><div class="bottom">${button(r.points?`Develop fighter · ${r.points} points`:'Your fighter','attributes')}<p class="town-note">${r.crown?'Moonsteel, Royal equipment and Meteor are now on sale. Thornkeeper is unlocked for your next journey.':r.level<3?'Win duels. Earn gold. Build your fighter. The tournament opens at level 3.':'The tournament is open. Keep training in duels, or challenge the crown when you are ready.'}</p></div>`;
if(view==='arena')screen.innerHTML=heading('Enter the arena','One rival. One decision.')+`<section class="panel center-panel stack">${button('<strong>Regular duel</strong><small>Win gold and a level. Defeat only costs gold.</small>','offer')}${button('<strong>The First Crown</strong><small>'+ (r.crown?'Crown claimed. New equipment unlocked.':r.level<3?'Unlocks at level 3.':'Three fights. One master. Defeat ends your journey.')+'</small>','tournament',r.level<3||r.crown)}${button('Back to town','town')}</section>`;
if(view==='offer'||view==='tournament'){const o=r.tournament?E.tournamentOffer(r):r.offer;screen.innerHTML=heading(r.tournament?`The First Crown · ${r.tournament.round+1} / 3`:'Your next rival',r.tournament?'Win every fight to claim the crown.':'Look at their strengths. Choose your fight.')+`<div class="rival-portrait-space"></div><section class="panel rival-panel"><h2>${o.name} <span class="tag">Level ${o.level} ${E.CLASSES[o.hero].title}</span></h2><p class="muted" style="text-align:center">${E.gearName(o.hero,'melee',o.gear.melee)} · ${E.gearName(o.hero,'defense',o.gear.defense)}${o.spells.length?' · '+o.spells.map(s=>E.SPELLS[s].name).join(', '):''}</p>${compare(o)}<p style="text-align:center">Win: <b>${o.reward} gold + 1 level</b><br><small>${r.tournament?'Lose: journey ends':`Lose: up to ${o.loss} gold`}</small></p><div class="buttons">${button(r.points?'Spend your attribute points first':'Fight!','fight',!!r.points,'gold')}${r.points?button('Develop fighter','attributes'):''}${!r.tournament?button('Find another rival','reroll')+button('Town','town'):''}</div></section>`;}
if(view==='attributes'){const descriptions={strength:'Stronger close-range attacks',speed:'More energy, movement and ranged damage',defense:'Reduce incoming physical damage',vitality:'Increase maximum health',magic:'Increase spell damage'};screen.innerHTML=heading('Build your fighter',r.points?`${r.points} points to spend. Choose your strategy.`:'Your choices shape every fight.')+`<section class="panel center-panel"><div class="attributes">${E.ATTRS.map(k=>`<div class="attribute"><span>${k[0].toUpperCase()+k.slice(1)}<small>${descriptions[k]}</small></span><b>${r.attrs[k]}</b>${button('+','stat:'+k,!r.points)}</div>`).join('')}</div>${button(r.tournament?'Next tournament fight':'Back to town',r.tournament?'next':'town',!!r.points,'gold')}</section>`;}
if(view==='shop'){const items=E.shop(r,category),p=items.find(i=>i.id===preview);screen.innerHTML=heading(category==='magic'?'Arcane Shop':category==='weapons'?'Weaponsmith':'Armory',E.CLASSES[r.hero].title+' equipment · Select an item to try it on.')+`<div class="shop-layout"><div class="shop-hero"></div><div><div class="shop-items">${items.map(i=>`<button class="item ${preview===i.id?'selected':''}" data-do="preview:${i.id}"><strong>${i.name}</strong><p>${i.desc}</p><small>${i.owned?'Owned':i.locked?'Win the crown to unlock':i.price+' gold'}</small></button>`).join('')}</div><div class="preview-box">${p?`<b>${p.name}</b><p>${previewDescription(p)}</p><div class="buttons">${button(p.owned?'Owned':p.locked?'Crown required':`Buy · ${p.price} gold`,'buy',p.owned||p.locked||r.gold<p.price,'gold')}${button('Try in arena','train')}</div>`:'Select equipment to preview the change. Try it in a free practice fight before buying.'}</div></div></div><div class="bottom">${button('Back to town','town')}</div>`;}
if(view==='fight'&&b){const names={p:E.CLASSES[r.hero].name,e:b.opponent.name};screen.innerHTML=`<div class="healths">${['p','e'].map(k=>`<div><b>${names[k]}</b><progress value="${b[k].hp}" max="${b[k].stats.hp}" aria-label="${names[k]} health"></progress><small>${b[k].hp} / ${b[k].stats.hp} HP · ${b[k].energy} energy</small><span class="status">${b[k].guard?'Guarding ':''}${b[k].shield?'Aegis ':''}${b[k].frost?'Slowed ':''}</span></div>`).join('')}</div><p class="combat-note" aria-live="polite">${b.log}<span class="turn-label">${training?'PRACTICE · ':''}${locked||b.turn==='e'?'Rival responding…':'Your turn · Choose one action'}</span></p><div class="action-dock"><p class="action-info">Distance: ${Math.abs(b.p.x-b.e.x)} · Melee reach: 2 · Every action uses your turn</p><div class="action-row">${E.actions(b,'p').map(a=>button(`${a.name}<small>${a.reason||`${a.cost} energy${a.chance?' · '+a.chance+'%':''}`}</small>`, 'act:'+a.id,locked||b.turn!=='p'||a.disabled)).join('')}${training?button('Leave practice','leave-training',locked):''}</div></div>`;for(const el of screen.querySelectorAll('[data-do^="act:"]')){const a=E.actions(b,'p').find(a=>a.id===el.dataset.do.slice(4));el.title=a.desc+(a.damage?` ${a.damage} damage before guard or shields.`:'');el.onpointerenter=()=>{screen.querySelector('.action-info').textContent=el.title;};}}
if(view==='result'){const v=r.result;screen.innerHTML=`<section class="panel center-panel result"><span class="tag">${v.master?'THE FIRST CROWN':v.dead?'TOURNAMENT DEFEAT':v.won?'WELL FOUGHT':'REGULAR DUEL'}</span><h1>${v.master?'Crowned!':v.won?'Victory!':v.dead?'Journey over':'Defeated'}</h1><p class="reward">${v.gold>=0?'+':''}${v.gold} gold</p><p>${v.master?'Thornkeeper unlocked! Higher-tier equipment is now on sale.':v.won?`Level ${r.level} · 3 attribute points` :v.dead?'Your unlocked masters remain available. Try a different fighter or strategy.':'Your journey continues. Upgrade, adapt and try again.'}</p><div class="buttons">${button(v.dead?'New journey':v.won?'Develop fighter':'Back to town',v.dead?'new':v.won?'attributes':'town',false,'gold')}</div></section>`;}
}
function previewRun(){const p=E.shop(run,category).find(i=>i.id===preview),r=structuredClone(run);if(p){if(category==='magic'){if(!r.spells.includes(p.id))r.spells.push(p.id);}else r.gear[p.slot]=p.tier;}return r;}
function previewDescription(p){if(category==='magic')return p.desc+` Costs ${p.cost} energy. Cooldown: ${p.cooldown} turns.`;const a=E.stats(run),b=E.stats(previewRun());return Object.keys(a).filter(k=>a[k]!==b[k]).map(k=>`${k}: ${a[k]} → ${b[k]}`).join(' · ')||'This item is already equipped.';}
screen.onclick=e=>{const el=e.target.closest('[data-do]');if(!el||el.disabled||locked)return;const [cmd,...tail]=el.dataset.do.split(':'),arg=tail.join(':');
if(cmd==='choose'){run=E.newRun(arg,meta);save();go('town');}
else if(cmd==='new'){run=null;save();go('choose');}
else if(cmd==='shop'){category=arg;go('shop');}
else if(cmd==='preview'){preview=arg;render();}
else if(cmd==='buy'){E.buy(run,category,preview);save();render();}
else if(cmd==='stat'){E.allocate(run,arg);save();render();}
else if(cmd==='offer'||cmd==='reroll'){if(!run.offer||cmd==='reroll')E.offer(run);save();go('offer');}
else if(cmd==='tournament'){if(run.points){go('attributes');return;}confirm('Enter the First Crown?','Three fights, ending with the Forest Master. Health and energy refill between fights. Shops close until the tournament ends. Any defeat ends your journey.','Enter tournament',()=>{if(E.enterTournament(run)){save();go('tournament');}});}
else if(cmd==='next')go('tournament');
else if(cmd==='fight'){if(E.startFight(run)){save();go('fight');}}
else if(cmd==='act')play(arg);
else if(cmd==='train'){training=previewRun();training.battle=null;training.tournament=null;training.points=0;training.dead=false;E.offer(training);E.startFight(training);go('fight');}
else if(cmd==='leave-training'){training=null;go('shop');}
else if(['town','arena','attributes'].includes(cmd)){if(run?.tournament&&cmd!=='attributes')go('tournament');else go(cmd);}
};
async function play(id){const r=training||run,b=r.battle;if(locked||!b||b.turn!=='p')return;locked=true;if(!E.act(b,id,'p')){locked=false;render();return;}if(!training)save();await animate(b);await finishTurn(r);}
function animate(b){animation={events:structuredClone(b.events),start:performance.now(),duration:matchMedia('(prefers-reduced-motion: reduce)').matches?80:520};render();return new Promise(resolve=>setTimeout(()=>{animation=null;resolve();},animation.duration));}
async function finishTurn(r){const b=r.battle;if(b.outcome){locked=false;if(training){training=null;go('shop');return;}E.settle(run,meta);save();go('result');return;}if(b.turn==='e'){locked=true;render();await new Promise(resolve=>setTimeout(resolve,250));E.act(b,E.ai(b),'e');if(!training)save();await animate(b);return finishTurn(r);}locked=false;render();}
function draw(time){const dpr=Math.min(devicePixelRatio||1,2),w=innerWidth,h=innerHeight;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const fight=view==='fight',im=fight?art?.forest:town;if(im){if(fight){const s=Math.max(w/im.width,h/im.height);ctx.drawImage(im,(w-im.width*s)/2,(h-im.height*s)/2,im.width*s,im.height*s);}else ctx.drawImage(im,0,0,w,h);}ctx.fillStyle=fight?'#102c2430':view==='town'?'#102c2410':'#102c2470';ctx.fillRect(0,0,w,h);
const paint=(kind,x,y,gear,scale,opts={})=>hero(ctx,art,kind,x,y,{...gear,magic:0},{scale,time:time/1000,...opts});
if(art){if(view==='choose'){['dwarf','ranger','mage'].forEach((k,i)=>paint(k,w*(.2+i*.3),h*.5,E.newRun(k).gear,Math.min(w/900,h/680)));}
else if(fight){const b=training?.battle||run.battle,dock=screen.querySelector('.action-dock'),floor=Math.max(h*.45,h-(dock?.offsetHeight||170)-35),map=x=>w*.09+x/18*w*.82,s=Math.min(w/680,h/600,.95);ctx.fillStyle='#ab9b6b';ctx.fillRect(w*.05,floor+7,w*.9,4);for(let n=0;n<=18;n++){ctx.fillStyle='#f1d79d77';ctx.fillRect(map(n)-1,floor+7,2,8);}for(const k of ['p','e']){const a=b[k],ev=animation?.events.find(v=>v.type==='action'&&v.who===k),t=animation?Math.min(1,(time-animation.start)/animation.duration):1,x=ev?ev.from+(ev.to-ev.from)*t:a.x,y=floor-(ev?.id==='jump'?Math.sin(t*Math.PI)*70:0);paint(a.hero,map(x),y,a.gear,s,{face:k==='p'?1:-1,moving:ev&&ev.from!==ev.to,walk:t*10,attack:ev&&['quick','normal','heavy','shoot'].includes(ev.id)?{t,duration:1}:null});if(a.guard||a.shield){ctx.strokeStyle=a.shield?'#a4deff':'#ffe49f';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(map(x),floor-80*s,60*s,100*s,0,0,Math.PI*2);ctx.stroke();}}
if(animation){const ev=animation.events[0],t=Math.min(1,(time-animation.start)/animation.duration),target=ev.who==='p'?'e':'p';if(['lightning','frost','meteor','sleep','shoot'].includes(ev.id)){ctx.strokeStyle=ev.id==='lightning'?'#fff2a0':ev.id==='sleep'?'#d4acff':'#9ce5ff';ctx.lineWidth=ev.id==='meteor'?12:4;ctx.beginPath();ctx.moveTo(map(b[ev.who].x),floor-100*s);ctx.lineTo(map(b[ev.who].x)+(map(b[target].x)-map(b[ev.who].x))*t,floor-95*s);ctx.stroke();}for(const hit of animation.events.filter(e=>e.type==='hit')){ctx.fillStyle='#ffe4aa';ctx.font='bold 26px Nunito';ctx.textAlign='center';ctx.fillText('-'+hit.damage,map(b[hit.target].x),floor-220*s-t*25);}}}
else if(view==='town')paint(run.hero,w*.48,h*.86,run.gear,Math.min(w/700,h/750,.8));
else if(view==='shop'){const box=screen.querySelector('.shop-hero')?.getBoundingClientRect();if(box)paint(run.hero,box.x+box.width/2,box.bottom-5,previewRun().gear,Math.min(box.height/270,1.15));}
else if(view==='offer'||view==='tournament'){const o=run.tournament?E.tournamentOffer(run):run.offer,box=screen.querySelector('.rival-portrait-space')?.getBoundingClientRect();if(box){const s=box.height/270;paint(run.hero,w*.38,box.bottom,run.gear,s);paint(o.hero,w*.62,box.bottom,o.gear,s,{face:-1});}}
}requestAnimationFrame(draw);}
try{[art,town]=await Promise.all([assets(),(async()=>{const i=new Image();i.src='assets/crownlands/town.webp';await i.decode();return i;})()]);$('loading').remove();view=run?.battle?'fight':run?.result?'result':run?.tournament?'tournament':run?'town':'choose';render();requestAnimationFrame(draw);if(run?.battle){locked=true;await finishTurn(run);}}catch(e){$('loading').textContent='Unable to load the arena. Please refresh to try again.';console.error(e);}
